// Verifies X-Intelligo-Signature (hex HMAC-SHA256 of the raw body).
// n8n env: N8N_WEBHOOK_SECRET, NODE_FUNCTION_ALLOW_BUILTIN=crypto, N8N_BLOCK_ENV_ACCESS_IN_NODE=false
const crypto = require('crypto');
const item = $input.first();
const raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
const signature = String(item.json.headers['x-intelligo-signature'] || '');
const expected = crypto.createHmac('sha256', $env.N8N_WEBHOOK_SECRET).update(raw, 'utf8').digest('hex');
const valid = signature.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(expected, 'hex'));
if (!valid) {
  throw new Error('Signature tidak valid');
}
return [{ json: JSON.parse(raw) }];

// DRY-RUN: logs instead of sending. Replace this node with your WhatsApp provider
// (Fonnte, Wablas, or WA Cloud API) when going live.
const envelope = $input.first().json;
const p = envelope.payload || {};
const recipients = p.recipients ? p.recipients : [{ to: p.to, name: p.recipient_name }];
return [{ json: { ok: true, dry_run: true, action_id: envelope.action_id, recipients: recipients.length } }];
